
import express from "express";
import session from "express-session";
import Database from "better-sqlite3";
import bcrypt from "bcryptjs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const db = new Database(path.join(__dirname, "metro.db"));
const PORT = process.env.PORT || 3000;

const INDEX_HTML = "\n<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#070916\">\n<title>МЕТРО — Армавир</title>\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<style>\n:root{\n  --bg:#050612; --panel:#0c0d1d; --panel2:#11132a; --text:#f6f7ff; --muted:#a7abc7;\n  --blue:#3d5cff; --violet:#7a4dff; --cyan:#38cfff; --line:rgba(255,255,255,.09);\n  --shadow:0 18px 60px rgba(29,34,150,.28); --r:24px;\n}\n*{box-sizing:border-box} html{scroll-behavior:smooth}\nbody{margin:0;background:radial-gradient(circle at 80% 0%,rgba(65,65,255,.22),transparent 34%),var(--bg);color:var(--text);font:500 16px/1.5 Inter,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\na{color:inherit;text-decoration:none} button,input,select,textarea{font:inherit}\nbutton{cursor:pointer}\n.wrap{width:min(1180px,calc(100% - 32px));margin:auto}\n.top{position:sticky;top:0;z-index:20;background:rgba(5,6,18,.72);backdrop-filter:blur(20px);border-bottom:1px solid var(--line)}\n.nav{height:72px;display:flex;align-items:center;justify-content:space-between}\n.brand{display:flex;align-items:center;gap:11px;font-size:25px;letter-spacing:.08em}\n.neon{color:#eef4ff;text-shadow:0 0 8px #4b65ff,0 0 24px #3156ff}\n.navlinks{display:flex;gap:24px;color:#c8cae0;font-size:14px}\n.navlinks a:hover{color:#fff}\n.btn{border:0;border-radius:15px;padding:12px 18px;color:white;background:linear-gradient(135deg,var(--blue),var(--violet));box-shadow:0 12px 35px rgba(72,75,255,.25)}\n.btn.ghost{background:rgba(255,255,255,.06);border:1px solid var(--line);box-shadow:none}\n.hero{min-height:calc(100vh - 72px);display:grid;align-items:center;position:relative;overflow:hidden}\n.hero:before{content:\"\";position:absolute;inset:-20%;background:radial-gradient(circle at 50% 30%,rgba(46,91,255,.24),transparent 35%),radial-gradient(circle at 75% 65%,rgba(120,56,255,.17),transparent 30%);filter:blur(15px)}\n.hero-grid{position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:40px;align-items:center}\n.kicker{color:#78d8ff;font-size:12px;text-transform:uppercase;letter-spacing:.22em}\nh1{font-size:clamp(56px,9vw,116px);line-height:.9;margin:18px 0;text-transform:uppercase;letter-spacing:-.06em}\n.hero h1 span{display:block}\n.hero p{max-width:580px;color:#b8bbd3;font-size:19px}\n.hero-card{border:1px solid var(--line);border-radius:32px;padding:10px;background:rgba(255,255,255,.04);box-shadow:var(--shadow);transform:rotate(2deg)}\n.hero-card img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:25px;filter:saturate(.9) contrast(1.05)}\n.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}\nsection{padding:90px 0}\n.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:30px}\n.eyebrow{font-size:12px;color:#6edbff;letter-spacing:.18em;text-transform:uppercase}\nh2{font-size:42px;line-height:1.05;margin:8px 0}\n.muted{color:var(--muted)}\n.grid{display:grid;gap:16px}\n.grid3{grid-template-columns:repeat(3,1fr)}\n.grid2{grid-template-columns:repeat(2,1fr)}\n.card{background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(255,255,255,.02));border:1px solid var(--line);border-radius:var(--r);padding:24px;box-shadow:var(--shadow)}\n.price{font-size:27px;font-weight:800}\n.item{display:flex;justify-content:space-between;gap:20px;padding:16px 0;border-bottom:1px solid var(--line)}\n.item:last-child{border-bottom:0}\n.tag{display:inline-flex;padding:5px 9px;border-radius:999px;background:rgba(80,102,255,.14);color:#9ba8ff;font-size:12px}\n.gallery{display:grid;grid-template-columns:1.25fr .75fr .75fr;grid-auto-rows:230px;gap:12px}\n.gallery img{width:100%;height:100%;object-fit:cover;border-radius:20px;border:1px solid var(--line)}\n.gallery img:first-child{grid-row:span 2}\n.news-card{overflow:hidden;padding:0}.news-card img{width:100%;height:190px;object-fit:cover}.news-body{padding:22px}\n.booking{background:linear-gradient(145deg,rgba(53,81,255,.18),rgba(124,70,255,.09));border:1px solid rgba(109,119,255,.25)}\nform{display:grid;gap:13px}.row{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}\nlabel{font-size:12px;color:#b7bbd2;display:grid;gap:7px}\ninput,select,textarea{width:100%;padding:13px 14px;border-radius:13px;border:1px solid var(--line);background:#090b18;color:#fff;outline:none}\ntextarea{min-height:95px;resize:vertical}\n.note{font-size:12px;color:#9ca1bd}\n.footer{padding:50px 0;border-top:1px solid var(--line);color:#969ab5}\n.bottom-nav{display:none}\n.modal{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.7);backdrop-filter:blur(12px);display:none;align-items:center;justify-content:center;padding:18px}\n.modal.show{display:flex}.modalbox{width:min(560px,100%);background:#0b0d1c;border:1px solid var(--line);border-radius:26px;padding:26px;max-height:90vh;overflow:auto}\n.close{float:right;background:transparent;color:#aaa;border:0;font-size:24px}\n.admin{display:none}.admin.show{display:block}\n.tabs{display:flex;gap:8px;overflow:auto;margin:18px 0}.tab{border:1px solid var(--line);background:#0d1020;color:#ddd;padding:10px 14px;border-radius:12px;white-space:nowrap}\n.tab.active{background:linear-gradient(135deg,var(--blue),var(--violet))}\n.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}\n.status{padding:5px 8px;border-radius:8px;background:rgba(255,255,255,.07);font-size:11px}\n.toast{position:fixed;right:18px;bottom:18px;z-index:100;display:none;padding:14px 17px;background:#11142a;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}\n.toast.show{display:block}\n@media(max-width:800px){\n .navlinks,.nav>.btn{display:none}.nav{height:62px}.hero-grid,.grid2,.grid3{grid-template-columns:1fr}.hero{min-height:auto;padding:65px 0 30px}.hero-card{max-width:420px;margin:auto}section{padding:65px 0}h2{font-size:34px}.gallery{grid-template-columns:1fr 1fr;grid-auto-rows:170px}.gallery img:first-child{grid-row:span 1}.row{grid-template-columns:1fr}.bottom-nav{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:30;background:rgba(7,8,20,.92);backdrop-filter:blur(18px);border-top:1px solid var(--line);justify-content:space-around;padding:10px 6px calc(10px + env(safe-area-inset-bottom));font-size:11px}.bottom-nav a{text-align:center;color:#b8bdd7}.bottom-nav b{display:block;color:#fff;font-size:17px}.table{display:block;overflow:auto;white-space:nowrap}}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <div class=\"wrap nav\">\n    <a class=\"brand\" href=\"#top\"><span class=\"neon\">МЕТРО</span></a>\n    <nav class=\"navlinks\">\n      <a href=\"#about\">О нас</a><a href=\"#menu\">Меню</a><a href=\"#news\">Новости</a><a href=\"#gallery\">Фото</a><a href=\"#contacts\">Контакты</a>\n    </nav>\n    <button class=\"btn\" onclick=\"openBooking()\">Забронировать</button>\n  </div>\n</header>\n\n<main id=\"top\">\n<section class=\"hero\">\n  <div class=\"wrap hero-grid\">\n    <div>\n      <div class=\"kicker\">Армавир · Розы Люксембург, 139</div>\n      <h1><span>МЕТРО</span><span class=\"neon\">Lounge</span></h1>\n      <p>Пространство для спокойного отдыха, разговоров и игры. Три отдельные комнаты, игровая зона, чай и кофе — всё в атмосфере холодного неона.</p>\n      <div class=\"actions\">\n        <button class=\"btn\" onclick=\"openBooking()\">Забронировать комнату</button>\n        <a class=\"btn ghost\" href=\"#menu\">Посмотреть меню</a>\n      </div>\n      <p class=\"note\" style=\"margin-top:18px\">Ежедневно · 14:00–02:00</p>\n    </div>\n    <div class=\"hero-card\"><img src=\"/assets/metro-6.jpg\" alt=\"Интерьер МЕТРО\"></div>\n  </div>\n</section>\n\n<section id=\"about\">\n  <div class=\"wrap\">\n    <div class=\"section-head\"><div><div class=\"eyebrow\">О пространстве</div><h2>Не просто посиделки.</h2></div><span class=\"tag\">3 комнаты</span></div>\n    <div class=\"grid grid3\">\n      <div class=\"card\"><div class=\"price\">03</div><h3>Отдельные комнаты</h3><p class=\"muted\">Три отдельных зала без классической посадки за столиками: 8, 10 и 6 человек. Вместимость и названия можно изменить в админ-панели.</p></div>\n      <div class=\"card\"><div class=\"price\">🎮</div><h3>Игровая зона</h3><p class=\"muted\">Место для игры и отдыха. Детали игровой зоны можно вынести в отдельную страницу позже.</p></div>\n      <div class=\"card\"><div class=\"price\">14:00</div><h3>До 02:00</h3><p class=\"muted\">Работаем ежедневно. Онлайн-бронирование доступно круглосуточно.</p></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"menu\">\n  <div class=\"wrap\">\n    <div class=\"section-head\"><div><div class=\"eyebrow\">Меню</div><h2>Для ознакомления.</h2></div><span class=\"tag\">актуальные цены</span></div>\n    <div class=\"grid grid2\">\n      <div class=\"card\"><h3>Чай / кофе</h3>\n        <div class=\"item\"><span>Ассам <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Эрл Грей <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Дикая вишня <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Молочный улун <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Таёжный сбор <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Те Гуань Инь <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Пуэр «Дворцовый» <small class=\"muted\">900 мл</small></span><b>300 ₽</b></div>\n        <div class=\"item\"><span>Чай чёрный пакетированный <small class=\"muted\">200 мл</small></span><b>50 ₽</b></div>\n        <div class=\"item\"><span>Кофе чёрный по-восточному <small class=\"muted\">100 мл</small></span><b>100 ₽</b></div>\n      </div>\n      <div class=\"card\"><h3>Условия посещения</h3>\n        <div class=\"item\"><span>Комната</span><b>250 ₽ / час</b></div>\n        <div class=\"item\"><span>Замена чаши</span><b>500 ₽</b></div>\n        <div class=\"item\"><span>Свой табак</span><b>800 ₽</b></div>\n        <div class=\"item\"><span>Пробковый сбор до 9% алкоголя</span><b>50 ₽</b></div>\n        <div class=\"item\"><span>Пробковый сбор после 9% алкоголя</span><b>100 ₽</b></div>\n        <div class=\"item\"><span>Доп. гость сверх вместимости</span><b>100 ₽ / час</b></div>\n        <div class=\"item\"><span>Задержка после времени брони</span><b>10 мин бесплатно</b></div>\n        <p class=\"note\">После бесплатных 10 минут задержка оплачивается как ещё один час.</p>\n      </div>\n    </div>\n    <p class=\"note\" style=\"margin-top:18px\">Информация и цены отображаются как справочные сведения о заведении. Актуальность условий следует проверять у администрации.</p>\n  </div>\n</section>\n\n<section id=\"news\">\n  <div class=\"wrap\">\n    <div class=\"section-head\"><div><div class=\"eyebrow\">Лента</div><h2>Что нового.</h2></div><button class=\"btn ghost\" onclick=\"loadNews()\">Обновить</button></div>\n    <div id=\"newsGrid\" class=\"grid grid3\"><div class=\"card\">Загрузка…</div></div>\n  </div>\n</section>\n\n<section id=\"gallery\">\n  <div class=\"wrap\">\n    <div class=\"section-head\"><div><div class=\"eyebrow\">Атмосфера</div><h2>МЕТРО в кадре.</h2></div></div>\n    <div class=\"gallery\">\n      <img src=\"/assets/metro-6.jpg\" alt=\"Интерьер\">\n      <img src=\"/assets/metro-1.jpg\" alt=\"Детали\">\n      <img src=\"/assets/metro-4.jpg\" alt=\"Игровая зона\">\n      <img src=\"/assets/metro-3.jpg\" alt=\"Чай\">\n      <img src=\"/assets/metro-7.jpg\" alt=\"Вывеска\">\n    </div>\n  </div>\n</section>\n\n<section id=\"contacts\">\n  <div class=\"wrap grid grid2\">\n    <div>\n      <div class=\"eyebrow\">Контакты</div><h2>Заезжай в МЕТРО.</h2>\n      <p class=\"muted\">Армавир, улица Розы Люксембург, 139</p>\n      <p><a class=\"btn\" href=\"tel:+79184600220\">Позвонить +7 918 460-02-20</a></p>\n      <div class=\"actions\">\n        <a class=\"btn ghost\" target=\"_blank\" href=\"https://yandex.ru/maps/?text=Армавир%20улица%20Розы%20Люксембург%20139\">Яндекс Карты</a>\n        <a class=\"btn ghost\" target=\"_blank\" href=\"https://2gis.ru/armawir/firm/70000001068016043\">2ГИС</a>\n        <a class=\"btn ghost\" target=\"_blank\" href=\"https://www.google.com/maps/search/?api=1&query=Армавир%2C%20улица%20Розы%20Люксембург%2C%20139\">Google Maps</a>\n      </div>\n    </div>\n    <div class=\"card\">\n      <h3>Обратная связь</h3>\n      <form id=\"feedbackForm\">\n        <div class=\"row\"><label>Имя<input name=\"name\" required></label><label>Телефон<input name=\"phone\"></label></div>\n        <label>Сообщение<textarea name=\"text\" required placeholder=\"Ваш вопрос или отзыв\"></textarea></label>\n        <button class=\"btn\">Отправить</button>\n      </form>\n    </div>\n  </div>\n</section>\n</main>\n\n<footer class=\"footer\"><div class=\"wrap\">© МЕТРО · Армавир · 2026</div></footer>\n\n<nav class=\"bottom-nav\">\n  <a href=\"#about\"><b>◌</b>О нас</a><a href=\"#menu\"><b>≡</b>Меню</a><a href=\"#top\" onclick=\"openBooking();return false\"><b>＋</b>Бронь</a><a href=\"#news\"><b>✦</b>Новости</a><a href=\"#contacts\"><b>⌖</b>Контакты</a>\n</nav>\n\n<div id=\"bookingModal\" class=\"modal\">\n  <div class=\"modalbox\">\n    <button class=\"close\" onclick=\"closeBooking()\">×</button>\n    <div class=\"eyebrow\">Онлайн-бронирование</div><h2>Забронировать комнату</h2>\n    <p class=\"muted\">Выберите дату, время и зал. Бронь длится 1 час; правила продления указаны в меню.</p>\n    <form id=\"bookingForm\">\n      <div class=\"row\"><label>Имя<input name=\"name\" required></label><label>Телефон<input name=\"phone\" required placeholder=\"+7 ...\"></label></div>\n      <div class=\"row\"><label>Гостей<input name=\"guests\" type=\"number\" min=\"1\" max=\"20\" value=\"2\" required></label><label>Комната<select name=\"room_id\" id=\"roomSelect\" required></select></label></div>\n      <div class=\"row\"><label>Дата<input name=\"date\" id=\"dateInput\" type=\"date\" required></label><label>Время<select name=\"time\" id=\"timeSelect\" required></select></label></div>\n      <label>С алкоголем / без<select name=\"alcohol\"><option value=\"without\">Без алкоголя</option><option value=\"with\">С алкоголем</option></select></label>\n      <label>Комментарий<textarea name=\"comment\" placeholder=\"Пожелания, дополнительные гости и т.д.\"></textarea></label>\n      <button class=\"btn\">Отправить заявку</button>\n      <div class=\"note\">После отправки заявка попадёт администратору. Финальное подтверждение — после проверки свободной комнаты.</div>\n    </form>\n  </div>\n</div>\n\n<div id=\"adminModal\" class=\"modal\">\n <div class=\"modalbox\">\n  <button class=\"close\" onclick=\"closeAdmin()\">×</button>\n  <div id=\"adminLogin\">\n    <div class=\"eyebrow\">Служебный вход</div><h2>Админ-панель</h2>\n    <form id=\"loginForm\"><label>Логин<input name=\"username\" required></label><label>Пароль<input name=\"password\" type=\"password\" required></label><button class=\"btn\">Войти</button><div class=\"note\">Демо-аккаунты указаны в README проекта. Перед запуском смените пароли.</div></form>\n  </div>\n  <div id=\"adminApp\" class=\"admin\">\n    <div style=\"display:flex;justify-content:space-between;gap:10px;align-items:center\"><div><div class=\"eyebrow\">Панель</div><h2>МЕТРО / Admin</h2></div><button class=\"btn ghost\" onclick=\"adminLogout()\">Выйти</button></div>\n    <div class=\"tabs\"><button class=\"tab active\" data-tab=\"bookings\">Брони</button><button class=\"tab\" data-tab=\"newsAdmin\">Новости</button><button class=\"tab\" data-tab=\"feedback\">Отзывы</button><button class=\"tab\" data-tab=\"rooms\">Комнаты</button></div>\n    <div id=\"tab-bookings\"></div>\n    <div id=\"tab-newsAdmin\" style=\"display:none\"></div>\n    <div id=\"tab-feedback\" style=\"display:none\"></div>\n    <div id=\"tab-rooms\" style=\"display:none\"></div>\n  </div>\n </div>\n</div>\n<div id=\"toast\" class=\"toast\"></div>\n\n<script>\nconst $=s=>document.querySelector(s);\nfunction toast(t){const e=$(\"#toast\");e.textContent=t;e.classList.add(\"show\");setTimeout(()=>e.classList.remove(\"show\"),3500)}\nfunction openBooking(){ $(\"#bookingModal\").classList.add(\"show\"); loadRooms(); }\nfunction closeBooking(){ $(\"#bookingModal\").classList.remove(\"show\") }\nfunction openAdmin(){ $(\"#adminModal\").classList.add(\"show\"); checkAdmin() }\nfunction closeAdmin(){ $(\"#adminModal\").classList.remove(\"show\") }\ndocument.addEventListener(\"keydown\",e=>{if(e.key===\"Escape\"){closeBooking();closeAdmin()}})\n\nasync function loadRooms(){\n const r=await fetch(\"/api/rooms\"); const rooms=await r.json();\n $(\"#roomSelect\").innerHTML=rooms.map(x=>`<option value=\"${x.id}\">${x.name} · до ${x.capacity} гостей</option>`).join(\"\");\n}\nfunction initTimes(){\n const s=$(\"#timeSelect\"); let a=[];\n for(let h=14;h<=23;h++) for(let m of [0,30]) a.push(`${String(h).padStart(2,\"0\")}:${String(m).padStart(2,\"0\")}`);\n for(let h=0;h<2;h++) for(let m of [0,30]) a.push(`${String(h).padStart(2,\"0\")}:${String(m).padStart(2,\"0\")}`);\n s.innerHTML=a.map(t=>`<option>${t}</option>`).join(\"\");\n}\ninitTimes();\nconst d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); $(\"#dateInput\").min=d.toISOString().slice(0,10); $(\"#dateInput\").value=d.toISOString().slice(0,10);\n\n$(\"#bookingForm\").addEventListener(\"submit\",async e=>{\n e.preventDefault(); const data=Object.fromEntries(new FormData(e.target));\n const r=await fetch(\"/api/bookings\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)});\n const j=await r.json(); if(!r.ok)return toast(j.error||\"Не удалось отправить заявку\");\n toast(\"Заявка принята. Администратор проверит комнату.\"); e.target.reset(); $(\"#dateInput\").value=d.toISOString().slice(0,10); closeBooking();\n});\n$(\"#feedbackForm\").addEventListener(\"submit\",async e=>{\n e.preventDefault(); const data=Object.fromEntries(new FormData(e.target));\n const r=await fetch(\"/api/feedback\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)}); const j=await r.json();\n if(!r.ok)return toast(j.error||\"Ошибка\"); toast(\"Спасибо! Сообщение отправлено.\"); e.target.reset();\n});\nasync function loadNews(){\n const r=await fetch(\"/api/news\"); const news=await r.json(); const grid=$(\"#newsGrid\");\n if(!news.length){grid.innerHTML=`<div class=\"card\"><h3>Пока тихо.</h3><p class=\"muted\">Новости и события появятся здесь из админ-панели.</p></div>`;return}\n grid.innerHTML=news.map(n=>`<article class=\"card news-card\">${n.image?`<img src=\"${n.image}\" alt=\"\">`:``}<div class=\"news-body\"><span class=\"tag\">${new Date(n.published_at).toLocaleDateString(\"ru-RU\")}</span><h3>${esc(n.title)}</h3><p class=\"muted\">${esc(n.body)}</p></div></article>`).join(\"\");\n}\nfunction esc(s){return String(s).replace(/[&<>\"']/g,m=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[m]))}\nloadNews();\n\nasync function checkAdmin(){\n const r=await fetch(\"/api/admin/me\");\n if(r.ok){$(\"#adminLogin\").style.display=\"none\";$(\"#adminApp\").classList.add(\"show\");loadAdminTab(\"bookings\")}\n else{$(\"#adminLogin\").style.display=\"block\";$(\"#adminApp\").classList.remove(\"show\")}\n}\n$(\"#loginForm\").addEventListener(\"submit\",async e=>{\n e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const r=await fetch(\"/api/admin/login\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)});const j=await r.json();\n if(!r.ok)return toast(j.error);toast(\"Вход выполнен\");checkAdmin();\n});\nasync function adminLogout(){await fetch(\"/api/admin/logout\",{method:\"POST\"});checkAdmin();toast(\"Вы вышли\")}\ndocument.querySelectorAll(\".tab\").forEach(b=>b.onclick=()=>{document.querySelectorAll(\".tab\").forEach(x=>x.classList.remove(\"active\"));b.classList.add(\"active\");loadAdminTab(b.dataset.tab)});\n\nasync function loadAdminTab(tab){\n [\"bookings\",\"newsAdmin\",\"feedback\",\"rooms\"].forEach(x=>$(\"#tab-\"+x).style.display=x===tab?\"block\":\"none\");\n if(tab===\"bookings\"){\n  const r=await fetch(\"/api/admin/bookings\");const a=await r.json();\n  $(\"#tab-bookings\").innerHTML=`<h3>Бронирования</h3><table class=\"table\"><tr><th>Дата</th><th>Гость</th><th>Комната</th><th>Комментарий</th><th>Статус</th></tr>${a.map(x=>`<tr><td>${x.date}<br>${x.time}</td><td>${esc(x.name)}<br>${esc(x.phone)}<br>${x.guests} чел.</td><td>${esc(x.room_name)}<br>${x.alcohol===\"with\"?\"С алкоголем\":\"Без алкоголя\"}</td><td>${esc(x.comment||\"—\")}</td><td><select onchange=\"setBookingStatus(${x.id},this.value)\">${[\"pending\",\"confirmed\",\"cancelled\",\"completed\"].map(s=>`<option ${s===x.status?\"selected\":\"\"}>${s}</option>`).join(\"\")}</select></td></tr>`).join(\"\")}</table>`;\n } else if(tab===\"newsAdmin\"){\n  const r=await fetch(\"/api/news\");const a=await r.json();\n  $(\"#tab-newsAdmin\").innerHTML=`<h3>Новая публикация</h3><form id=\"newsForm\"><input name=\"title\" placeholder=\"Заголовок\" required><textarea name=\"body\" placeholder=\"Текст\" required></textarea><input name=\"image\" placeholder=\"/assets/metro-1.jpg\"><input name=\"published_at\" type=\"datetime-local\" required><button class=\"btn\">Опубликовать</button></form><h3 style=\"margin-top:28px\">Опубликовано</h3>${a.map(x=>`<div class=\"card\" style=\"margin:10px 0\"><b>${esc(x.title)}</b><p class=\"muted\">${esc(x.body)}</p><button class=\"btn ghost\" onclick=\"deleteNews(${x.id})\">Удалить</button></div>`).join(\"\")}`;\n  $(\"#newsForm\").addEventListener(\"submit\",async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const r=await fetch(\"/api/admin/news\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)return toast(j.error);toast(\"Новость опубликована\");loadAdminTab(\"newsAdmin\");loadNews()})\n } else if(tab===\"feedback\"){\n  const r=await fetch(\"/api/admin/feedback\");const a=await r.json();$(\"#tab-feedback\").innerHTML=`<h3>Обратная связь / отзывы</h3><table class=\"table\"><tr><th>Дата</th><th>Имя</th><th>Телефон</th><th>Сообщение</th></tr>${a.map(x=>`<tr><td>${x.created_at}</td><td>${esc(x.name)}</td><td>${esc(x.phone||\"\")}</td><td>${esc(x.text)}</td></tr>`).join(\"\")}</table>`;\n } else {\n  const r=await fetch(\"/api/rooms\");const a=await r.json();$(\"#tab-rooms\").innerHTML=`<h3>Комнаты</h3>${a.map(x=>`<div class=\"card\" style=\"margin:10px 0\"><div class=\"row\"><label>Название<input id=\"rn${x.id}\" value=\"${esc(x.name)}\"></label><label>Вместимость<input id=\"rc${x.id}\" type=\"number\" value=\"${x.capacity}\"></label></div><button class=\"btn\" onclick=\"saveRoom(${x.id})\">Сохранить</button></div>`).join(\"\")}`;\n }\n}\nasync function setBookingStatus(id,status){const r=await fetch(\"/api/admin/bookings/\"+id,{method:\"PATCH\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({status})});if(r.ok)toast(\"Статус обновлён\");else toast(\"Ошибка\")}\nasync function deleteNews(id){if(!confirm(\"Удалить новость?\"))return;await fetch(\"/api/admin/news/\"+id,{method:\"DELETE\"});loadAdminTab(\"newsAdmin\");loadNews()}\nasync function saveRoom(id){const data={name:$(\"#rn\"+id).value,capacity:$(\"#rc\"+id).value};const r=await fetch(\"/api/admin/rooms/\"+id,{method:\"PATCH\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(data)});if(r.ok){toast(\"Комната сохранена\");loadRooms()}}\n\ndocument.addEventListener(\"keydown\",e=>{if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()===\"a\"){e.preventDefault();openAdmin()}})\n</script>\n</body>\n</html>\n";
const MANIFEST = "{\n  \"name\":\"МЕТРО — Армавир\",\n  \"short_name\":\"МЕТРО\",\n  \"start_url\":\"/\",\n  \"display\":\"standalone\",\n  \"background_color\":\"#050612\",\n  \"theme_color\":\"#070916\",\n  \"lang\":\"ru\"\n}";
const IMAGES = {"metro-2.jpg":"","metro-1.jpg":"","metro-6.jpg":"","metro-5.jpg":"","metro-7.jpg":"","metro-3.jpg":"","metro-4.jpg":""};

app.get("/", (req,res) => res.type("html").send(INDEX_HTML));
app.get("/manifest.webmanifest", (req,res) => res.type("application/manifest+json").send(MANIFEST));
app.get("/assets/:name", (req,res) => {
  const b64 = IMAGES[req.params.name];
  if (!b64) return res.status(404).end();
  res.type("jpg").send(Buffer.from(b64, "base64"));
});

app.use(express.json());
app.use(express.urlencoded({extended:true}));
app.use(session({
  secret: process.env.SESSION_SECRET || "change-this-secret-in-production",
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: "lax", secure: false, maxAge: 1000*60*60*12 }
}));

db.exec(`
CREATE TABLE IF NOT EXISTS admins (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rooms (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  capacity INTEGER NOT NULL DEFAULT 4,
  active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS bookings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  guests INTEGER NOT NULL,
  date TEXT NOT NULL,
  time TEXT NOT NULL,
  room_id INTEGER NOT NULL,
  comment TEXT,
  alcohol TEXT NOT NULL DEFAULT 'without',
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS news (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  image TEXT,
  published_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS feedback (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  phone TEXT,
  text TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
`);

const adminCount = db.prepare("SELECT COUNT(*) c FROM admins").get().c;
if (!adminCount) {
  const seed = [
    ["admin1", "metro-admin-1", "Администратор 1"],
    ["admin2", "metro-admin-2", "Администратор 2"],
    ["admin3", "metro-admin-3", "Администратор 3"]
  ];
  const stmt = db.prepare("INSERT INTO admins(username,password_hash,name) VALUES(?,?,?)");
  for (const [u,p,n] of seed) stmt.run(u, bcrypt.hashSync(p, 10), n);
}
const roomCount = db.prepare("SELECT COUNT(*) c FROM rooms").get().c;
if (!roomCount) {
  const stmt = db.prepare("INSERT INTO rooms(id,name,capacity) VALUES(?,?,?)");
  stmt.run(1, "Зал 1", 8);
  stmt.run(2, "Зал 2", 10);
  stmt.run(3, "Зал 3", 6);
}

function adminOnly(req,res,next){
  if (!req.session.adminId) return res.status(401).json({error:"Требуется вход администратора"});
  next();
}

app.get("/api/rooms", (req,res) => {
  res.json(db.prepare("SELECT id,name,capacity FROM rooms WHERE active=1 ORDER BY id").all());
});

app.get("/api/news", (req,res) => {
  res.json(db.prepare("SELECT * FROM news ORDER BY published_at DESC, id DESC LIMIT 20").all());
});

app.post("/api/bookings", (req,res) => {
  const {name,phone,guests,date,time,room_id,comment="",alcohol="without"} = req.body;
  if (!name || !phone || !guests || !date || !time || !room_id) {
    return res.status(400).json({error:"Заполните обязательные поля"});
  }
  const room = db.prepare("SELECT * FROM rooms WHERE id=? AND active=1").get(room_id);
  if (!room) return res.status(400).json({error:"Комната не найдена"});
  if (Number(guests) > Number(room.capacity)) {
    return res.status(400).json({error:`В комнате ${room.name} базовая вместимость ${room.capacity} гостей. Дополнительные гости оплачиваются отдельно.`});
  }
  const conflict = db.prepare(`
    SELECT COUNT(*) c FROM bookings
    WHERE room_id=? AND date=? AND time=? AND status IN ('pending','confirmed')
  `).get(room_id,date,time).c;
  if (conflict) return res.status(409).json({error:"На это время комната уже забронирована. Выберите другое время."});

  const info = db.prepare(`
    INSERT INTO bookings(name,phone,guests,date,time,room_id,comment,alcohol)
    VALUES(?,?,?,?,?,?,?,?)
  `).run(name,phone,Number(guests),date,time,room_id,comment,alcohol);

  res.json({ok:true,id:info.lastInsertRowid});
});

app.post("/api/feedback", (req,res) => {
  const {name,phone="",text} = req.body;
  if (!name || !text) return res.status(400).json({error:"Заполните имя и сообщение"});
  db.prepare("INSERT INTO feedback(name,phone,text) VALUES(?,?,?)").run(name,phone,text);
  res.json({ok:true});
});

app.post("/api/admin/login", (req,res) => {
  const {username,password} = req.body;
  const admin = db.prepare("SELECT * FROM admins WHERE username=?").get(username);
  if (!admin || !bcrypt.compareSync(password,admin.password_hash)) {
    return res.status(401).json({error:"Неверный логин или пароль"});
  }
  req.session.adminId = admin.id;
  req.session.adminName = admin.name;
  res.json({ok:true,name:admin.name});
});
app.post("/api/admin/logout", (req,res) => req.session.destroy(()=>res.json({ok:true})));
app.get("/api/admin/me", adminOnly, (req,res)=>res.json({name:req.session.adminName}));

app.get("/api/admin/bookings", adminOnly, (req,res) => {
  res.json(db.prepare(`
    SELECT b.*, r.name room_name FROM bookings b
    JOIN rooms r ON r.id=b.room_id
    ORDER BY b.date DESC, b.time DESC, b.id DESC
  `).all());
});
app.patch("/api/admin/bookings/:id", adminOnly, (req,res) => {
  const {status} = req.body;
  if (!["pending","confirmed","cancelled","completed"].includes(status)) return res.status(400).json({error:"Некорректный статус"});
  db.prepare("UPDATE bookings SET status=? WHERE id=?").run(status,req.params.id);
  res.json({ok:true});
});
app.get("/api/admin/feedback", adminOnly, (req,res) => {
  res.json(db.prepare("SELECT * FROM feedback ORDER BY id DESC").all());
});
app.post("/api/admin/news", adminOnly, (req,res) => {
  const {title,body,image="",published_at} = req.body;
  if (!title || !body || !published_at) return res.status(400).json({error:"Заполните заголовок, текст и дату"});
  const info = db.prepare("INSERT INTO news(title,body,image,published_at) VALUES(?,?,?,?)").run(title,body,image,published_at);
  res.json({ok:true,id:info.lastInsertRowid});
});
app.patch("/api/admin/news/:id", adminOnly, (req,res) => {
  const {title,body,image="",published_at} = req.body;
  db.prepare("UPDATE news SET title=?,body=?,image=?,published_at=? WHERE id=?")
    .run(title,body,image,published_at,req.params.id);
  res.json({ok:true});
});
app.delete("/api/admin/news/:id", adminOnly, (req,res) => {
  db.prepare("DELETE FROM news WHERE id=?").run(req.params.id);
  res.json({ok:true});
});
app.patch("/api/admin/rooms/:id", adminOnly, (req,res) => {
  const {name,capacity,active=1} = req.body;
  db.prepare("UPDATE rooms SET name=?,capacity=?,active=? WHERE id=?")
    .run(name,Number(capacity),active?1:0,req.params.id);
  res.json({ok:true});
});

app.listen(PORT,()=>console.log(`METRO site: http://localhost:${PORT}`));
